#include <cuda_runtime.h>
#include <vector>
#include <fstream>
#include <chrono>
#include <cmath>
#include <cstddef>
#include "../nbody-cuda/Particle.hpp"
#include "../nbody-cuda/GSimulationKernels.hpp"
static_assert(sizeof(Particle)==40&&offsetof(Particle,mass)==36&&offsetof(Particle,acc)==24&&offsetof(Particle,vel)==12,"Source Particle ABI");
const float ESENT=-8192.25f;
void ck(cudaError_t e){if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(2);}}
std::vector<double>load(const char*f){std::ifstream io(f,std::ios::binary|std::ios::ate);size_t z=io.tellg();std::vector<double>a(z/8);io.seekg(0);io.read((char*)a.data(),z);return a;}
Particle sentinel(){Particle p;float*x=(float*)&p;for(int i=0;i<10;i++)x[i]=ESENT;return p;}
bool isguard(const Particle&p){auto*x=(const float*)&p;for(int i=0;i<10;i++)if(x[i]!=ESENT)return false;return true;}
void append(std::vector<double>&out,const std::vector<Particle>&v){for(auto&p:v)for(int i=0;i<10;i++)out.push_back(((const float*)&p)[i]);}
struct Case{int n,steps;float dt,soft,g;std::vector<Particle>initial;Particle*raw,*p,*qraw,*q;float*eraw,*e;};
void reset(Case&c){ck(cudaMemcpy(c.p,c.initial.data(),c.n*40,cudaMemcpyHostToDevice));ck(cudaMemcpy(c.q,c.initial.data(),c.n*40,cudaMemcpyHostToDevice));ck(cudaMemset(c.e,0,c.n*4));ck(cudaDeviceSynchronize());}
void launch(Case&c){accelerate_particles<<<(c.n+255)/256,256>>>(c.p,c.n,c.soft,c.g);update_particles<<<(c.n+255)/256,256>>>(c.p,c.e,c.n,c.dt);accumulate_energy<<<1,1>>>(c.e,c.n);ck(cudaDeviceSynchronize());}
int main(){auto f=load(NBODY_FIXTURE),oracle=load(NBODY_ORACLE),budget=load(NBODY_BUDGET);std::vector<Case>cases;size_t pos=1;for(int i=0;i<int(f[0]);i++){Case c;c.n=f[pos++];c.steps=f[pos++];c.dt=f[pos++];c.soft=f[pos++];c.g=f[pos++];c.initial.resize(c.n);for(auto&p:c.initial)for(int k=0;k<10;k++)((float*)&p)[k]=float(f[pos++]);std::vector<Particle>pr(c.n+2,sentinel());std::copy(c.initial.begin(),c.initial.end(),pr.begin()+1);ck(cudaMalloc(&c.raw,pr.size()*40));c.p=c.raw+1;ck(cudaMemcpy(c.raw,pr.data(),pr.size()*40,cudaMemcpyHostToDevice));ck(cudaMalloc(&c.qraw,pr.size()*40));c.q=c.qraw+1;ck(cudaMemcpy(c.qraw,pr.data(),pr.size()*40,cudaMemcpyHostToDevice));std::vector<float>er(c.n+8,ESENT);std::fill(er.begin()+4,er.end()-4,0.f);ck(cudaMalloc(&c.eraw,er.size()*4));c.e=c.eraw+4;ck(cudaMemcpy(c.eraw,er.data(),er.size()*4,cudaMemcpyHostToDevice));cases.push_back(c);}for(auto&c:cases)for(int step=0;step<c.steps;step++)launch(c);
for(int trial=1;trial<=5;trial++){auto payload=f;bool ok=true;double total=0,maxerr=0,maxnorm=0;size_t oi=0;std::vector<double>times,step_times;auto check=[&](const std::vector<double>&v){for(double x:v){double y=oracle[oi],b=budget[oi++],err=fabs(x-y);maxerr=std::max(maxerr,err);maxnorm=std::max(maxnorm,b>0?err/b:err==0?0:1e300);ok&=std::isfinite(x)&&err<=b;}};
for(auto&c:cases){reset(c);double ct=0;for(int step=0;step<c.steps;step++){auto start=std::chrono::steady_clock::now();launch(c);double tm=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();ct+=tm;total+=tm;step_times.push_back(tm);std::vector<Particle>p(c.n+2);std::vector<float>e(c.n+8);ck(cudaMemcpy(p.data(),c.raw,p.size()*40,cudaMemcpyDeviceToHost));ck(cudaMemcpy(e.data(),c.eraw,e.size()*4,cudaMemcpyDeviceToHost));float ke=.5f*e[4];ok&=isguard(p.front())&&isguard(p.back());for(int j=0;j<4;j++)ok&=e[j]==ESENT&&e[e.size()-1-j]==ESENT;std::vector<double>values;append(values,std::vector<Particle>(p.begin()+1,p.end()-1));for(int j=0;j<c.n;j++)values.push_back(e[j+4]);values.push_back(ke);check(values);for(int j=0;j<c.n;j++){ok&=p[j+1].mass==c.initial[j].mass;for(int k=0;k<3;k++)ok&=p[j+1].acc[k]==0.f;}append(payload,p);for(float x:e)payload.push_back(x);payload.push_back(ke);}times.push_back(ct);accelerate_particles<<<(c.n+255)/256,256>>>(c.q,c.n,c.soft,c.g);ck(cudaDeviceSynchronize());std::vector<Particle>q(c.n+2);ck(cudaMemcpy(q.data(),c.qraw,q.size()*40,cudaMemcpyDeviceToHost));ok&=isguard(q.front())&&isguard(q.back());std::vector<double>values;append(values,std::vector<Particle>(q.begin()+1,q.end()-1));check(values);for(int j=0;j<c.n;j++){ok&=q[j+1].mass==c.initial[j].mass;for(int k=0;k<3;k++)ok&=q[j+1].pos[k]==c.initial[j].pos[k]&&q[j+1].vel[k]==c.initial[j].vel[k];}append(payload,q);}
std::string path="trial_"+std::to_string(trial)+".bin";std::ofstream io(path,std::ios::binary);io.write((char*)payload.data(),payload.size()*8);io.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_error_budget_ratio\":%.17g,\"timing_region\":\"sum15_step_core_accel_update_serialenergy_context_complete\",\"jit_excluded\":true,\"internal_repeats\":1,\"timed_kernel_calls\":45,\"force_capture\":\"untimed_initial_state_force_replay_after_all_timed_captures\",\"case_times_seconds\":[",trial,total,ok?"true":"false",payload.size(),maxerr,maxnorm);for(size_t i=0;i<times.size();i++)printf("%s%.17g",i?",":"",times[i]);printf("],\"step_times_seconds\":[");for(size_t i=0;i<step_times.size();i++)printf("%s%.17g",i?",":"",step_times[i]);printf("],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",path.c_str(),payload.size());if(!ok)return 3;}}
